mapper.select:
/* 연도학기목록조회 */ SELECT SC.SMSTR_CHRT_ID , SC.DGRS_YR , SC.DGRS_SMSTR_CHRT , SC.SMSTR_CHRTNM , SC.SMSTR_CHRT_GBNCD , SC.NOW_SMSTRYN , SC.DGRS_YR || SC.DGRS_SMSTR_CHRT YR_SMSTR , CASE WHEN NVL(SC.SMSTR_CHRT_GBNCD, 'SMSTR') = 'SMSTR' THEN SC.DGRS_YR || '년도 ' || SC.DGRS_SMSTR_CHRT || '학기' ELSE SC.DGRS_YR || '년도 ' || SC.DGRS_SMSTR_CHRT || '기수' END YR_SMSTRNM FROM TB_LMS_SMSTR_CHRT SC WHERE 1 = 1
AND SC.ORG_ID = #{orgId}
AND SC.DGRS_YR = #{dgrsYr}
AND SC.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}
